WITH metrics AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, COUNT(amount) OVER (PARTITION BY account_id) AS account_id_count_amount, SUM(amount) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_amount, LEAD(amount, 1) OVER (PARTITION BY account_id ORDER BY amount, id) AS next_amount, FIRST_VALUE(merchant) IGNORE NULLS OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_merchant FROM transactions) SELECT DATE_TRUNC('QUARTER', txn_time) AS quarter_start, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS duration_min, COUNT_IF(merchant = 'Lazada') AS lazada_events, AVG(account_id_count_amount) FILTER (WHERE txn_type = 'DEBIT') AS debit_avg_account_id_count_amount, MIN(txn_time) AS first_seen, COUNT_IF(txn_type = 'CREDIT') AS credit_events FROM metrics GROUP BY DATE_TRUNC('QUARTER', txn_time);
